    "Script": "AppTheming = {
  init: async function(app, container) {
      app = app || session.app;
      container =
          container || $(".component[name=AppTheming]");

      var themeList =
          $(".component[name=AppThemeList]", container);

      if (themeList.length) {
          await AppThemeList.init(app, themeList);
      }

      AppTheming.wireUpEvents(container);
      AppTheming.hideMissingPreviews(container);
  },

    wireUpEvents: function(container) {
        AppTheming.wireUpFileUploading(
            $("input[name=brand-logo]", container),
            $("img[name=brand-logo-preview]", container),
            "Content/CompanyLogo.png"
        );

        AppTheming.wireUpFileUploading(
            $("input[name=project-logo]", container),
            $("img[name=project-logo-preview]", container),
            "Content/CompanyLogo2.png"
        );

        AppTheming.wireUpFileUploading(
            $("input[name=animation]", container),
            $("img[name=animation-preview]", container),
            "Content/background.gif"
        );
    },

    wireUpFileUploading: function(element, preview, path) {
        element
            .off("change.appTheming")
            .on("change.appTheming", function(event) {
                return AppTheming.handleFileUploadEvent(
                    event,
                    preview,
                    path
                );
            });
    },

    handleFileUploadEvent: async function(
        event,
        preview,
        path
    ) {
        var files = event.target.files || [];

        if (files.length > 1) {
            error("Select one file only");
            return;
        }

        if (!files.length) {
            return;
        }

        AppTheming.handleFileUploadPreview(
            files[0],
            preview
        );

        await api.file.upload(path, files[0]);

        notification.success(
            "[resource_displayname[saved]]"
        );
    },

    handleFileUploadPreview: function(file, preview) {
        var objectUrl = URL.createObjectURL(file);

        preview
            .removeClass("asset-missing")
            .attr("src", objectUrl)
            .one("load", function() {
                URL.revokeObjectURL(objectUrl);
            });
    },

    hideMissingPreviews: function(container) {
        $(".app-theming-preview img", container).each(
            function() {
                var image = $(this);

                image
                    .off("error.appTheming")
                    .on("error.appTheming", function() {
                        image.addClass("asset-missing");
                    });

                if (
                    this.complete &&
                    !this.naturalWidth
                ) {
                    image.addClass("asset-missing");
                }
            }
        );
    }
};",
