                template: (data) => (data.Entity.DisplayName && data.Entity.DisplayName.length > 80) ? CommonCacheResources.escapeHtml(data.Entity.DisplayName.substring(0, 80)) + '...' : CommonCacheResources.escapeHtml(data.Entity.DisplayName), encoded: true },
				
