                template: (data) => (data.Entity.ShortDisplayName && data.Entity.ShortDisplayName.length > 80) ? CommonCacheResources.escapeHtml(data.Entity.ShortDisplayName.substring(0, 80)) + '...' : CommonCacheResources.escapeHtml(data.Entity.ShortDisplayName), 
