	save: async function (e, grid) {
		e.preventDefault();

		var item = grid.dataItem(
			$(e.currentTarget).closest("tr")
		);

		if (!item) return;

		var dupe = item.toJSON
			? item.toJSON()
			: JSON.parse(JSON.stringify(item));

		dupe.Key = item.Entity.Key;
		dupe.Name = item.Name;
		dupe.Entity.Key = item.Entity.Key;
		dupe.Entity.Name = item.Name;
		dupe.Json = JSON.stringify(dupe.Entity);

		delete dupe.Entity;
		delete dupe.uid;
		delete dupe.dirty;
		delete dupe.dirtyFields;

		try {
			await api.update(
				"ContentManagement/CommonObject(" + item.Id + ")",
				dupe
			);

			notification.success("[resource_displayname[saved]]");

			await api.get("RefreshCache");

			notification.success("[resource_displayname[rebuilt]]");
			grid.refresh();
		} catch (err) {
			error(err);
		}
	},

