			var editorContainer = $("[name=componentEditor]", e.detailRow);
			["content", "script"].forEach((name) => {
				var tabId = `component-${name}-tab-${component.Id}`;
				var paneId = `component-${name}-${component.Id}`;
				$(`[data-editor-tab=${name}]`, editorContainer).attr({
					id: tabId,
					"data-bs-target": `#${paneId}`,
					"aria-controls": paneId
				});
				$(`[data-editor-pane=${name}]`, editorContainer).attr({
					id: paneId,
					"aria-labelledby": tabId
				});
			});
			if ($(e.detailRow).find(".monaco-editor").length === 0) {
				var contentEditor = $(e.detailRow).find("div[name=content]");
				var scriptEditor = $(e.detailRow).find("div[name=script]");
				var html = new HTMLMonacoEditor(contentEditor[0], {
					code: component.Content
				});
				var script = new JavaScriptMonacoEditor(scriptEditor[0], {
					code: component.Script
				});
				html.onChange = (e) => {
					component.Content = html.getValue();
				}; 
				script.onChange = (e) => {
					component.Script = script.getValue();
				};
				var resizeEditors = () => {
					html.editor?.layout();
					script.editor?.layout();
				};
				html.init();
				script.init();
				$("[data-bs-toggle=tab]", editorContainer).on("shown.bs.tab", resizeEditors);
