    "Script": "ResourceManagement = {
	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=ResourceManagement]");
		api.addToMetaCache([
		{
        "Name": "ContentManagement",
        "Types": [
            [meta[ContentManagement/Resource]]
        ]
    }]);
		var config = {
			endpoint: "ContentManagement/Resource",
			odataAppend: "?$filter=AppId eq " + app.Id + " and Culture eq ''",
			group: { field: "Key" }
		};
		let cultures = await api.get("ContentManagement/Culture");
		let resourceDataSource = await model.getDatasource(config);
		let typeInfo = await api.getType("ContentManagement/Resource");
		await ResourceManagement.setupGrid(app,container,resourceDataSource, cultures, typeInfo);
	},

	setupGrid: async function(app,container, resourceDataSource, cultures, typeInfo) {
		var grid = new GridWidget(container, resourceDataSource);
        grid.toolbar = [
        {
            template: "<div class='btn-group btn-group-sm'> \
                <button class='btn btn-primary' name='create'> \
                    <span class='k-icon k-i-plus'></span>[resource_displayname[new]] \
                </button> \
                <button class='btn btn-primary' name='migrate'> \
                    <span class='k-icon k-i-arrow-up'></span>[resource_displayname[migrate]] \
                </button> \
            </div>"
        }];
		grid.filterable = true;
		grid.searchable = true;
		grid.search = { fields: ["Key", "Name", "DisplayName", "ShortDisplayName", "Description", "LastUpdatedBy"] }; 
		grid.columns = [
			{ field: "Key", editable: false, title: "[resource_shortdisplayname[key]]", width: 80 },
			{ field: "Name", editable: false, title: "[resource_shortdisplayname[name]]", width: 200 },
			{ field: "DisplayName", title: "[resource_shortdisplayname[displayname]]", template: (data) => (data.DisplayName && data.DisplayName.length > 80) ? ResourceManagement.escapeHtml(data.DisplayName.substring(0, 80)) + '...' : ResourceManagement.escapeHtml(data.DisplayName || ""), encoded: true },
			{ field: "ShortDisplayName", title: "[resource_shortdisplayname[shortdisplayname]]", template: (data) => (data.ShortDisplayName && data.ShortDisplayName.length > 80) ? ResourceManagement.escapeHtml(data.ShortDisplayName.substring(0, 80)) + '...' : ResourceManagement.escapeHtml(data.ShortDisplayName || ""), encoded: true },
			{ field: "Description", title: "[resource_shortdisplayname[description]]", template: (data) => (data.Description && data.Description.length > 80) ? ResourceManagement.escapeHtml(data.Description.substring(0, 80)) + '...' : ResourceManagement.escapeHtml(data.Description || ""), encoded: true },
			{ field: "LastUpdated", title: "[resource_displayname[lastupdated]]", width: 120, type: "date", format: "{0:g}" },
			{ field: "LastUpdatedBy", title: "[resource_displayname[lastupdated]]", width: 200 },
		];
		grid.commands.push({name: "save", icon: "k-i-save", text: "[resource_displayname[save]]"});
		grid.commands.push({name: "destroy", icon: "k-i-trash", text: "[resource_displayname[delete]]"});
		grid.detailTemplate =  "<div name='translations'></div>",
		grid.detailExpand = (e) => ResourceManagement.expandResource(e, app, grid, cultures.value, typeInfo);
		grid.dataBound = function() {
			$("[name=save]", grid.gridElement)
				.off("click.resourceManagement")
				.on("click.resourceManagement", function(e) {
					return ResourceManagement.save(e, grid);
				});

			$("[name=destroy]", grid.gridElement)
				.off("click.resourceManagement")
				.on("click.resourceManagement", function(e) {
					return ResourceManagement.destroy(e, grid);
				});
		};
		await grid.init();
		$("button[name=migrate]", grid.gridElement).on("click", (e) => ResourceManagement.migrate(app));
		$("button[name=create]", grid.gridElement).on("click", (e) => ResourceManagement.newResource(e, app, grid));
		$("input[name='searchResourcing']", grid.gridElement).off("keyup").keyup(ResourceManagement.delay((e) => ResourceManagement.search(e, grid, container, app, typeInfo), 500));
	},

	delay: function (callback, ms) {
		var timer = 0;
		return function () {
			var context = this, args = arguments;
			clearTimeout(timer);
			timer = setTimeout(function () {
				callback.apply(context, args);
			}, ms || 0);
		};
	},

	search: async function (grid, app, typeInfo) {
		var searchTerm = $("input[name='searchResourcing']", grid.gridElement).val();
		let data = await api.get("ContentManagement/Resource?$filter=AppId eq " + app.Id + " and Culture eq '' and (contains(Name, '" + searchTerm + "') or contains(DisplayName, '" + searchTerm + "') or contains(Description, '" + searchTerm + "') or contains(ShortDisplayName, '" + searchTerm + "') or contains(Key, '" + searchTerm + "'))");
		$.each(data.value, function (idx, item) {
			model.prepareItem(item, typeInfo);
		});
		grid.dataSource().data(data.value);
		grid.refresh();
	},

	expandResource: async function (e, app, grid, cultures, typeInfo) {
		var resource = grid.dataItem(e.masterRow);
		var container = $(e.detailRow);
		if($("[name=translationsGrid]", container).length === 0) {
			let translations = (await api.get("ContentManagement/Resource?$filter=AppId eq " + app.Id + " and Key eq '" + resource.Key + "' and Name eq '" + resource.Name + "' and Culture ne '' ")).value.map(r => {
				model.prepareItem(r, typeInfo);
				return r;
			});
			await ResourceManagement.setupTranslationsGrid(app,$("[name=translations]", container),resource,translations,cultures,typeInfo,grid)}
	},

	escapeHtml: function(html) {
    	return html.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#039;');
	},

	setupTranslationsGrid: async function(app,container,resource,translations,cultures,typeInfo,parentGrid) {
		var translationsGrid =
			new GridWidget(container, translations);

		translationsGrid.groupable = false;
		translationsGrid.pageable = false;
		translationsGrid.filterable = false;

		translationsGrid.toolbar = [
			{
				template: `
					<button
						type="button"
						class="btn btn-sm btn-primary"
						name="createTranslation"
					>
						<span class="k-icon k-i-plus"></span>
						[resource_displayname[newtranslation]]
					</button>
				`
			}
		];

		translationsGrid.columns = [
			{
				field: "Culture",
				editable: false,
				title: "[resource_shortdisplayname[culture]]"
			},
			{
				field: "DisplayName",
				title: "[resource_shortdisplayname[displayname]]"
			},
			{
				field: "ShortDisplayName",
				title:
					"[resource_shortdisplayname[shortdisplayname]]"
			},
			{
				field: "Description",
				title: "[resource_shortdisplayname[description]]"
			}
		];

		translationsGrid.commands.push({
			name: "save",
			icon: "k-i-save",
			text: "[resource_displayname[save]]"
		});

		translationsGrid.commands.push({
			name: "delete",
			icon: "k-i-trash",
			text: "[resource_displayname[delete]]"
		});

		translationsGrid.dataBound = function() {
			$("[name=save]", translationsGrid.gridElement)
				.off("click.resourceManagement")
				.on("click.resourceManagement", function(e) {
				return ResourceManagement.saveTranslation(
					e,
					app,
					resource,
					translationsGrid,
					parentGrid
				);
				});

			$("[name=delete]", translationsGrid.gridElement)
				.off("click.resourceManagement")
				.on("click.resourceManagement", function(e) {
					return ResourceManagement.destroy(
						e,
						translationsGrid
					);
				});
		};

		await translationsGrid.init();

		$(
			"button[name=createTranslation]",
			translationsGrid.gridElement
		)
			.off("click.resourceManagement")
			.on("click.resourceManagement", function(e) {
				e.preventDefault();

				return ResourceManagement.createTranslation(
					e,
					app,
					resource,
					translationsGrid,
					cultures,
					typeInfo
				);
			});
	},

	createTranslation: async function(e,app,resource,translationsGrid,cultures,typeInfo) {
		e.preventDefault();

		var options = cultures.filter(function(culture) {
			var alreadyExists =
				translationsGrid
					.dataSource()
					.data()
					.some(function(translation) {
						return (
							translation.Culture === culture.Id
						);
					});

			return culture.Id !== "" && !alreadyExists;
		});

		ResourceManagement.getCultureFromUser(
			options,
			async function(culture) {
				var newTranslation = {
					Id: 0,
					AppId: app.Id,
					Culture: culture,

					// Preserve the parent identity.
					Key: resource.Key,
					Name: resource.Name,

					DisplayName:
						resource.DisplayName || "",
					ShortDisplayName:
						resource.ShortDisplayName || "",
					Description:
						resource.Description || ""
				};

				try {
					var createdTranslation = await api.add(
						"ContentManagement/Resource",
						newTranslation
					);

					model.prepareItem(
						createdTranslation,
						typeInfo
					);

					translationsGrid
						.dataSource()
						.add(createdTranslation);

					notification.success(
						"[resource_displayname[translationcreated]]"
							.replace(
								"[culture]",
								createdTranslation.Culture
							)
					);
				} catch (err) {
					error(err);
				}
			}
		);
	},

		saveTranslation: async function(e,app,parentResource,translationsGrid,parentGrid) {
		e.preventDefault();

		var row = $(e.currentTarget).closest("tr");
		var kendoGrid = translationsGrid.kendoObject;
		var currentCell = null;

		if (
			kendoGrid &&
			typeof kendoGrid.current === "function"
		) {
			currentCell = kendoGrid.current();
		}

		if (
			currentCell &&
			currentCell.length > 0 &&
			typeof kendoGrid.closeCell === "function"
		) {
			kendoGrid.closeCell();
		}

		await Promise.resolve();

		var translation =
			translationsGrid.dataItem(row);

		if (!translation) {
			error("Unable to find the selected translation.");
			return;
		}

		var translationUpdate = {
			Id: translation.Id,
			AppId: app.Id,
			Key: parentResource.Key,
			Name: parentResource.Name,
			Culture: translation.Culture,
			DisplayName: translation.DisplayName || "",
			ShortDisplayName:
				translation.ShortDisplayName || "",
			Description: translation.Description || ""
		};

		try {
			await api.put(
				`ContentManagement/Resource(${translation.Id})`,
				translationUpdate
			);

			await api.put(
				`ContentManagement/Resource(${translation.Id})`,
				translationUpdate
			);

			parentGrid.refresh();

			notification.success(
				"[resource_displayname[saved]]"
			);
		} catch (err) {
			error(err);
		}
	},

	getCultureFromUser: function (options, callback) {
		var culture = null;
		var d = new Dialog({
			width: Math.min(600, window.innerWidth - 40),
			title: "[resource_displayname[newtranslation]]"
		});
		d.template = $("script[name=newTranslation]").html();
		d.events.confirm = function () {
			callback(culture.val());
			d.events.close();
		};
  d.init(function () {
      culture = $("select[name=\"culture\"]", d.element)
          .kendoDropDownList({
              dataTextField: "Name",
              dataValueField: "Id",
              dataSource: options,
              index: 0
          });

      culture.data("kendoDropDownList")
          .wrapper
          .css("width", "100%");
});
	},

	migrate: function (app) {
		var d = new Dialog({ width: Math.min(1100, window.innerWidth - 40), height: Math.min(600, window.innerHeight - 80), title: "[resource_displayname[migrate]]" });
		d.template = $("[name=resourceMigrationComponent]").first().html();
		d.init(() =>  ResourceMigration.init(app, $(".component[name=ResourceMigration]", d.element)));
	},


	newResource: async function (e, app, grid) {
		e.preventDefault();

		var createResourceDialog = new Dialog({
			width: Math.min(600, window.innerWidth - 40),
			height: "auto",
			title: "[resource_displayname[newresource]]"
		});

		createResourceDialog.template =
			$("script[name=\"newResourceDialog\"]")
				.first()
				.html();

		createResourceDialog.events.create = async function (e) {
			e.preventDefault();

			var resource = {
				Id: 0,
				AppId: app.Id,
				Culture: "",
				Key: $("input[name=\"key\"]", createResourceDialog.element).val(),
				Name: $("input[name=\"name\"]", createResourceDialog.element).val(),
				DisplayName: $("input[name=\"displayName\"]", createResourceDialog.element).val(),
				ShortDisplayName: $("input[name=\"shortDisplayName\"]", createResourceDialog.element).val(),
				Description: $("input[name=\"description\"]", createResourceDialog.element).val()
			};

			try {
				await api.add(
					"ContentManagement/Resource",
					resource
				);

				notification.success(
					"[resource_displayname[created]]"
				);

				grid.refresh();
				createResourceDialog.events.close();
			} catch (err) {
				error(err);
			}
		};

		await createResourceDialog.init();
	},

	save: async function(e, grid) {
		e.preventDefault();

		var resource = grid.dataItem(
			$(e.currentTarget).closest("tr")
		);

		if (!resource) {
			error("Unable to find the selected resource.");
			return;
		}

		var resourceUpdate = {
			Id: resource.Id,
			AppId: resource.AppId,
			Culture: resource.Culture,
			Key: resource.Key,
			Name: resource.Name,
			DisplayName: resource.DisplayName,
			ShortDisplayName: resource.ShortDisplayName,
			Description: resource.Description
		};

		try {
			var savedResource = await api.put(
				`ContentManagement/Resource(${resource.Id})`,
				resourceUpdate
			);

			if (savedResource) {
				resource.set(
					"DisplayName",
					savedResource.DisplayName
				);

				resource.set(
					"ShortDisplayName",
					savedResource.ShortDisplayName
				);

				resource.set(
					"Description",
					savedResource.Description
				);
			}

			notification.success(
				"[resource_displayname[saved]]"
			);

			grid.refresh();
		} catch (err) {
			error(err);
		}
	},

	destroy: function (e, grid) {
		e.preventDefault();
		var resource = grid.dataItem($(e.currentTarget).closest("tr"));
		var d = new ConfirmDialog({ 
			title: "[resource_displayname[areyousure]]",
			question: "[resource_displayname[areyousure]]",
			confirm: "[resource_displayname[confirm]]",
			close: "[resource_displayname[close]]"
		});
		d.events.confirm = async function () {
			d.events.close();
			await api.destroy("ContentManagement/Resource(" + resource.Id + ")").then(async () => {
				notification.success("[resource_displayname[deleted]]");
				grid.refresh();
			}).catch((err) => error(err));
		};
		d.init();
	}
