  {
    "Name": "ThemeBuilder",
    "Key": "ContentManagement",
    "ResourceKey": "ContentManagement",
    "Script": "ThemeBuilder = {
    init: async function(app, container, theme) {
        app = app || session.app;
        container =
            container || $(".component[name=ThemeBuilder]");

        if (!theme) {
            return;
        }

        theme.colours = theme.colours || {};

        if (
            !Array.isArray(theme.colours.charts) ||
            !theme.colours.charts.length
        ) {
            theme.colours.charts = [
                "#000000",
                "#000000",
                "#000000",
                "#000000",
                "#000000",
                "#000000"
            ];
        }

        if (!theme.cultureFlagLayout) {
            theme.cultureFlagLayout = "text";
        }

        var model = new kendo.observable(theme);

        kendo.bind(container, model);
        container.data("model", model);

        await Colours.init(
            app,
            $(".component[name=Colours]", container),
            model
        );

        await Font.init(
            app,
            $(".component[name=Font]", container),
            model
        );

        await Border.init(
            app,
            $(".component[name=Border]", container),
            model
        );

        await Notifications.init(
            app,
            $(".component[name=Notifications]", container)
        );

        await Shadows.init(
            app,
            $(".component[name=Shadows]", container),
            model
        );

        await Etc.init(
            app,
            $(".component[name=Etc]", container)
        );

        $(".partsList > ul > li", container)
            .off("click.themeBuilder")
            .on("click.themeBuilder", function(e) {
                e.preventDefault();

                var selectedItem = $(this);
                var targetName =
                    selectedItem.attr("data-container");

                $(".partsList > ul > li", container)
                    .removeClass("selected");

                $(".container", container)
                    .css("display", "none");

                $(
                    `.container[name="${targetName}"]`,
                    container
                ).css("display", "inline-block");

                selectedItem.addClass("selected");
            });
    },

    build: function(container) {
        var model = $(container).data("model");

        if (!model) {
            throw new Error(
                "ThemeBuilder has not been initialized."
            );
        }

        return model.toJSON();
    }
};",
    "Content": "<div class="partsList">
	<ul>
		<li class="selected" data-container="colourComponent">[resource_displayname[colours]]</li>
		<li data-container="fontComponent">[resource_displayname[font]]</li>
		<li data-container="border">[resource_displayname[border]]</li>
		<li data-container="notifications">[resource_displayname[notifications]]</li>
		<li data-container="shadows">[resource_displayname[shadows]]</li>
		<li data-container="etc">[resource_displayname[etc]]</li>
	</ul>
</div>
<div name="colourComponent" class="container">[component[Colours]]</div>
<div name="fontComponent" class="container" style="display:none;">[component[Font]]</div>
<div name="border" class="container" style="display:none;">[component[Border]]</div>
<div name="notifications" class="container" style="display:none;">[component[Notifications]]</div>
<div name="shadows" class="container" style="display:none;">[component[Shadows]]</div>
<div name="etc" class="container" style="display:none">[component[Etc]]</div>

<style>
.component[name=ThemeBuilder] {
    display: grid;
    grid-template-columns: 160px minmax(0, 1fr);
    gap: 18px;
    width: 100%;
    min-height: 460px;
    padding: 18px;
    overflow: auto;
    box-sizing: border-box;
    align-items: start;
}

/* Section navigation */
.component[name=ThemeBuilder] .partsList {
    position: sticky;
    top: 0;
    width: auto;
    height: auto;
    padding: 8px;
    border: 1px solid #d8dde5;
    border-radius: 8px;
    background: #f5f7fa;
}

.component[name=ThemeBuilder] .partsList > ul {
    display: grid;
    gap: 5px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.component[name=ThemeBuilder] .partsList > ul > li {
    width: auto;
    margin: 0;
    padding: 9px 11px;
    cursor: pointer;
    color: #334155;
    background: transparent;
    border-radius: 6px;
    transition:
        color 0.15s ease,
        background-color 0.15s ease;
}

.component[name=ThemeBuilder] .partsList > ul > li:hover {
    background: #e5eaf1;
}

.component[name=ThemeBuilder] .partsList > ul > li.selected {
    width: auto;
    color: #fff;
    font-weight: 600;
    background: #244b78;
}

/* Active editor panel */
.component[name=ThemeBuilder] > .container {
    grid-column: 2;
    grid-row: 1;
    width: 100%;
    max-width: none;
    min-width: 0;
    margin: 0;
    padding: 0;
}

/* Embedded editor components */
.component[name=ThemeBuilder] .component[name=Colours],
.component[name=ThemeBuilder] .component[name=Font],
.component[name=ThemeBuilder] .component[name=Border],
.component[name=ThemeBuilder] .component[name=Notifications],
.component[name=ThemeBuilder] .component[name=Shadows],
.component[name=ThemeBuilder] .component[name=Etc] {
    width: 100%;
    max-width: none;
    height: auto;
    margin: 0;
    padding: 0;
}

/* Prevent global Kendo styles leaking beyond ThemeBuilder */
.component[name=ThemeBuilder] span.k-select > span {
    display: none !important;
}

@media (max-width: 650px) {
    .component[name=ThemeBuilder] {
        grid-template-columns: 1fr;
    }

    .component[name=ThemeBuilder] .partsList {
        position: static;
    }

    .component[name=ThemeBuilder] .partsList > ul {
        grid-template-columns: repeat(3, 1fr);
    }

    .component[name=ThemeBuilder] > .container {
        grid-column: 1;
        grid-row: auto;
    }
}
</style>",
