  {
    "ResourceKey": "DocumentManagement",
    "Content": "",
    "Script": "FolderRoles = {
    init: async function (app, container, folder) {
        app = app || session.app;
        container = $('.component[name="FolderRoles"]');
        if (!folder) { return; }

        var rolesInApp = await api.get(
            "AppSecurity/Role?$filter=AppId eq " + app.Id
        );
        FolderRoles.setup(container, folder, rolesInApp.value);
    },

    setup: async function (container, folder, rolesInApp) {
        var folderRoleResponse = await api.get(
            "DocumentManagement/FolderRole?$filter=FolderId eq " +
            folder.Id
        );
        var normaliseId = function (value) {
            return String(value || "").toLowerCase();
        };
        var assignedRoleIds = new Set(
            (folderRoleResponse.value || []).map(function (item) {
                return normaliseId(item.RoleId);
            })
        );

        var grid = new GridWidget(container, {
            data: rolesInApp,
            sort: { field: "Name", dir: "asc" }
        });
        grid.toolbar =
            "<button class='btn btn-sm btn-primary' name='applyRecursively'>" +
            "<span class='k-icon k-i-arrow-rotate-cw'></span>" +
            "[resource_displayname[applyrecursively]]" +
            "</button>";
        grid.columns = [
            { selectable: true, width: "50px" },
            { field: "Name", title: "[resource_displayname[name]]" }
        ];
        grid.groupable = false;
        grid.pageable = false;
        grid.filterable = false;
        var suppressSelectionChange = false;

        var restoreAssignedSelection = function (kendoGrid) {
            suppressSelectionChange = true;
            kendoGrid.clearSelection();

            $("tr", kendoGrid.tbody).each(function () {
                var row = $(this);
                var dataItem = kendoGrid.dataItem(row);

                if (
                    dataItem &&
                    assignedRoleIds.has(normaliseId(dataItem.Id))
                ) {
                    kendoGrid.select(row);
                }
            });

            suppressSelectionChange = false;
        };

        grid.dataBound = function (e) {
            restoreAssignedSelection(e.sender);
        };

        grid.change = async function (e) {
            if (suppressSelectionChange) {
                return;
            }

            var kendoGrid = e.sender;
            var selectedRoleIds = new Set();
            var roleById = {};

            $("tr", kendoGrid.tbody).each(function () {
                var dataItem = kendoGrid.dataItem($(this));
                if (dataItem) {
                    roleById[normaliseId(dataItem.Id)] = dataItem;
                }
            });

            kendoGrid.select().each(function () {
                var dataItem = kendoGrid.dataItem($(this));
                if (dataItem) {
                    selectedRoleIds.add(normaliseId(dataItem.Id));
                }
            });

            var rolesToAdd = Array.from(selectedRoleIds).filter(
                function (roleId) {
                    return !assignedRoleIds.has(roleId);
                }
            );
            var rolesToRemove = Array.from(assignedRoleIds).filter(
                function (roleId) {
                    return !selectedRoleIds.has(roleId) && roleById[roleId];
                }
            );

            suppressSelectionChange = true;

            try {
                for (var i = 0; i < rolesToAdd.length; i++) {
                    await api.post(
                        "DocumentManagement/FolderRole",
                        {
                            FolderId: folder.Id,
                            RoleId: roleById[rolesToAdd[i]].Id
                        }
                    );
                    assignedRoleIds.add(rolesToAdd[i]);
                }

                for (var j = 0; j < rolesToRemove.length; j++) {
                    await api.post(
                        "DocumentManagement/FolderRole/Delete",
                        {
                            Value: [{
                                FolderId: folder.Id,
                                RoleId: roleById[rolesToRemove[j]].Id
                            }]
                        }
                    );
                    assignedRoleIds.delete(rolesToRemove[j]);
                }

                if (rolesToAdd.length || rolesToRemove.length) {
                    notification.success(
                        "[resource_displayname[saved]]"
                    );
                }
            } catch (err) {
                restoreAssignedSelection(kendoGrid);
                error(err);
            } finally {
                suppressSelectionChange = false;
            }
        };

        await grid.init();

        $("[name=applyRecursively]", grid.gridElement)
            .on("click", function (e) {
                return FolderRoles.applyRecursively(e, folder, grid);
            });

    },

    applyRecursively: async function (e, folder, grid) {
        e.preventDefault();
        $("[name=applyRecursively]", grid.gridElement)
            .html(
                "<span class='k-icon k-i-loading'></span>" +
                "[resource_displayname[applyrecursively]]"
            )
            .off("click");

        var baseSet = (
            await api.get(
                "DocumentManagement/FolderRole?$filter=FolderId eq " +
                folder.Id
            )
        ).value.map(function (item) {
            return item.RoleId;
        });

        await FolderRoles.applyRecursiveInternal(folder, baseSet);
        notification.success("[resource_displayname[applied]]");

        $("[name=applyRecursively]", grid.gridElement)
            .html("[resource_displayname[applyrecursively]]")
            .on("click", function (event) {
                return FolderRoles.applyRecursively(event, folder, grid);
            });
    },

    applyRecursiveInternal: async function (folder, roleIds) {
        notification.info(
            "[resource_displayname[applyroles]]: " + folder.Path
        );

        var currentFolder = await api.get(
            "DocumentManagement/Folder(" + folder.Id + ")" +
            "?$expand=SubFolders,Roles"
        );
        var existingFolderRoleIds = currentFolder.Roles
            .filter(function (item) {
                return roleIds.includes(item.RoleId);
            })
            .map(function (item) {
                return item.RoleId;
            });
        var newFolderRoleIds = roleIds.filter(function (roleId) {
            return !existingFolderRoleIds.includes(roleId);
        });

        for (var i = 0; i < newFolderRoleIds.length; i++) {
            await api.post("DocumentManagement/FolderRole", {
                FolderId: folder.Id,
                RoleId: newFolderRoleIds[i]
            });
        }

        for (var j = 0; j < currentFolder.SubFolders.length; j++) {
            await FolderRoles.applyRecursiveInternal(
                currentFolder.SubFolders[j],
                roleIds
            );
        }
    }
};
",
